query IssueLinks($owner: String!, $repo: String!, $number: Int!, $link0Owner: String!, $link0Repo: String!, $link0Number: Int!, $link1Owner: String!, $link1Repo: String!, $link1Number: Int!, $link2Owner: String!, $link2Repo: String!, $link2Number: Int!, $link3Owner: String!, $link3Repo: String!, $link3Number: Int!) {
  repository(owner: $owner, name: $repo) {
    issueOrPullRequest(number: $number) { __typename ... on Issue { id title } }
  }
  link0: repository(owner: $link0Owner, name: $link0Repo) {
    issueOrPullRequest(number: $link0Number) { __typename ... on Issue { id title state blocking(first: 50) { nodes { id } } } }
  }
  link1: repository(owner: $link1Owner, name: $link1Repo) {
    issueOrPullRequest(number: $link1Number) { __typename ... on Issue { id title state blocking(first: 50) { nodes { id } } } }
  }
  link2: repository(owner: $link2Owner, name: $link2Repo) {
    issueOrPullRequest(number: $link2Number) { __typename ... on Issue { id title state blocking(first: 50) { nodes { id } } } }
  }
  link3: repository(owner: $link3Owner, name: $link3Repo) {
    issueOrPullRequest(number: $link3Number) { __typename ... on Issue { id title state blocking(first: 50) { nodes { id } } } }
  }
}

